function removeDuplicates(arr) {
    if (!Array.isArray(arr)) {
        // Handles non-array input by returning an empty array
        return [];
    }

    const uniqueArr = [];
    for (let i = 0; i < arr.length; i++) {
        // Checks if the current element is already in uniqueArr
        if (uniqueArr.indexOf(arr[i]) === -1) {
            uniqueArr.push(arr[i]);
        }
    }
    return uniqueArr;
}

